import { apiClient, unwrap, type BffResponse } from '../api';

const BASE = '/accounting/financial-plans';

export interface FinancialPlanListItem {
  sttRec: string;
  soCt: string;
  ngayKh1: string;
  ngayKh2: string;
}

export interface FinancialPlanLine {
  sttRec0: string;
  tkNo: string;
  tkCo: string;
  maTd5I: string;
  psNt: number;
  dienGiaii: string;
  ps: number;
}

export interface FinancialPlan {
  sttRec: string;
  maCt: string;
  maGd: string;
  maPost: string;
  ngayCt: string;
  ngayLct: string;
  soCt: string;
  thang: number;
  nam: number;
  ngayKh1: string;
  ngayKh2: string;
  maKh: string;
  maBpH: string;
  maHsH: string;
  ongBa: string;
  diaChi: string;
  dienGiai: string;
  maNt: string;
  tyGia: number;
  lines: FinancialPlanLine[];
}

export interface FinancialPlanWriteLine {
  sttRec0?: string;
  tkNo: string | null;
  tkCo: string | null;
  maTd5I: string | null;
  psNt: number | null;
  dienGiaii: string | null;
  ps?: number;
}

export interface FinancialPlanWrite {
  maGd: string;
  maPost: string;
  maCt: string;
  ngayCt: string | null;
  ngayLct: string | null;
  soCt: string | null;
  thang: number;
  nam: number;
  ngayKh1: string | null;
  ngayKh2: string | null;
  maKh: string | null;
  maBpH: string | null;
  maHsH: string | null;
  ongBa: string | null;
  diaChi: string | null;
  dienGiai: string | null;
  maNt: string | null;
  tyGia: number | null;
  lines: FinancialPlanWriteLine[];
}

function withQuery(path: string, query: Record<string, string | number | boolean>): string {
  const params = new URLSearchParams();
  Object.entries(query).forEach(([key, value]) => {
    params.set(key, String(value));
  });
  const qs = params.toString();
  return qs ? `${path}?${qs}` : path;
}

export async function listFinancialPlans(
  query: Record<string, string | number | boolean>,
): Promise<FinancialPlanListItem[]> {
  const res = await apiClient.get<BffResponse<FinancialPlanListItem[]>>(withQuery(BASE, query));
  return unwrap(res);
}

export async function getFinancialPlan(sttRec: string): Promise<FinancialPlan> {
  const res = await apiClient.get<BffResponse<FinancialPlan>>(`${BASE}/${encodeURIComponent(sttRec)}`);
  return unwrap(res);
}

export async function createFinancialPlan(body: FinancialPlanWrite): Promise<FinancialPlan> {
  const res = await apiClient.post<BffResponse<FinancialPlan>>(BASE, body);
  return unwrap(res);
}

export async function updateFinancialPlan(sttRec: string, body: FinancialPlanWrite): Promise<FinancialPlan> {
  const res = await apiClient.put<BffResponse<FinancialPlan>>(
    `${BASE}/${encodeURIComponent(sttRec)}`,
    body,
  );
  return unwrap(res);
}
