import React, { useCallback, useEffect, useState } from 'react';
import { format, parseISO } from 'date-fns';
import { Button, Checkbox, Input, Select } from '@linm-soft-org/linm-web-common-components';
import { useInAppNavigate } from '../../../router/useInAppNavigate';
import { getApiErrorMessage } from '../../../utils/getApiErrorMessage';
import {
  listFinancialPlans,
  type FinancialPlanListItem,
} from '../../../services/kt/financialPlans';
import df from '../../../styles/documentForm.module.css';

interface SearchState {
  ngayCt1: string;
  ngayCt2: string;
  soCt1: string;
  soCt2: string;
  maKh: string;
  maKho: string;
  maVt: string;
  dienGiai: string;
  maGd: string;
  maPost: string;
  nhVt1: string;
  nhVt2: string;
  nhVt3: string;
  nhVt4: string;
  nhVt5: string;
  tien1: string;
  tien2: string;
  maPhi: string;
  maVv: string;
  maHd: string;
  maSp: string;
  maKu: string;
  maTtln: string;
  maTtcp: string;
  maBp: string;
  maHs: string;
  maCd: string;
  maTd1: string;
  maTd2: string;
  maTd3: string;
  maTd4: string;
  maTd5: string;
  locNsd: boolean;
}

const emptySearch = (): SearchState => ({
  ngayCt1: '',
  ngayCt2: '',
  soCt1: '',
  soCt2: '',
  maKh: '',
  maKho: '',
  maVt: '',
  dienGiai: '',
  maGd: '',
  maPost: '9',
  nhVt1: '',
  nhVt2: '',
  nhVt3: '',
  nhVt4: '',
  nhVt5: '',
  tien1: '',
  tien2: '',
  maPhi: '',
  maVv: '',
  maHd: '',
  maSp: '',
  maKu: '',
  maTtln: '',
  maTtcp: '',
  maBp: '',
  maHs: '',
  maCd: '',
  maTd1: '',
  maTd2: '',
  maTd3: '',
  maTd4: '',
  maTd5: '',
  locNsd: false,
});

function formatDate(value: string | null | undefined): string {
  if (!value) return '';
  try {
    const parsed = parseISO(value);
    if (Number.isNaN(parsed.getTime())) return value;
    return format(parsed, 'dd/MM/yyyy');
  } catch {
    return value;
  }
}

function amountQuery(raw: string): number | undefined {
  const text = raw.trim();
  if (!text) return undefined;
  const value = Number(text);
  if (!Number.isFinite(value)) return undefined;
  return value;
}

function buildSearchQuery(search: SearchState): Record<string, string | number | boolean> {
  const query: Record<string, string | number | boolean> = {
    maPost: search.maPost === '3' ? '3' : '9',
  };
  const textKeys: (keyof SearchState)[] = [
    'ngayCt1', 'ngayCt2', 'soCt1', 'soCt2', 'maKh', 'maKho', 'maVt', 'dienGiai',
    'nhVt1', 'nhVt2', 'nhVt3', 'nhVt4', 'nhVt5',
    'maPhi', 'maVv', 'maHd', 'maSp', 'maKu', 'maTtln', 'maTtcp',
    'maBp', 'maHs', 'maCd', 'maTd1', 'maTd2', 'maTd3', 'maTd4', 'maTd5',
  ];
  textKeys.forEach(key => {
    const value = String(search[key]).trim();
    if (value) query[key] = value;
  });
  if (search.maGd === '2' || search.maGd === '4') query.maGd = search.maGd;
  const tien1 = amountQuery(search.tien1);
  const tien2 = amountQuery(search.tien2);
  if (tien1 !== undefined) query.tien1 = tien1;
  if (tien2 !== undefined) query.tien2 = tien2;
  if (search.locNsd) query.locNsd = true;
  return query;
}

const Kh9ListPage: React.FC = () => {
  const navigate = useInAppNavigate();
  const [search, setSearch] = useState<SearchState>(emptySearch);
  const [filtering, setFiltering] = useState(false);
  const [items, setItems] = useState<FinancialPlanListItem[]>([]);
  const [selectedSttRec, setSelectedSttRec] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);

  const keepSelection = (rows: FinancialPlanListItem[]) => {
    setItems(rows);
    setSelectedSttRec(prev => (rows.some(row => row.sttRec === prev) ? prev : ''));
  };

  const loadOpen = useCallback(async () => {
    setLoading(true);
    setError('');
    try {
      const rows = await listFinancialPlans({ loadTop: 5 });
      keepSelection(rows);
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(getApiErrorMessage(err, 'Không tải được danh sách kế hoạch tài chính'));
    } finally {
      setLoading(false);
    }
  }, []);

  const loadSearch = useCallback(async (current: SearchState) => {
    setLoading(true);
    setError('');
    try {
      const rows = await listFinancialPlans(buildSearchQuery(current));
      keepSelection(rows);
    } catch (err) {
      setItems([]);
      setSelectedSttRec('');
      setError(getApiErrorMessage(err, 'Không tải được danh sách kế hoạch tài chính'));
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    void loadOpen();
  }, [loadOpen]);

  const onSearch = () => {
    setFiltering(true);
    void loadSearch(search);
  };

  const onRefresh = () => {
    if (filtering) void loadSearch(search);
    else void loadOpen();
  };

  const onEnter = (event: React.KeyboardEvent) => {
    if (event.key !== 'Enter') return;
    event.preventDefault();
    onSearch();
  };

  const setText = (key: keyof SearchState) => (event: React.ChangeEvent<HTMLInputElement>) => {
    setSearch(prev => ({ ...prev, [key]: event.target.value }));
  };

  const noSelection = !selectedSttRec;

  return (
    <div className={df.page} data-testid="ct-kh9-list">
      <h1 data-testid="ct-kh9-title">Kế hoạch tài chính</h1>
      <div className={df.headerActions}>
        <Button variant="secondary" data-testid="ct-kh9-toolbar-refresh-btn" onClick={onRefresh}>Làm mới</Button>
        <Button variant="primary" data-testid="ct-kh9-toolbar-add-btn" onClick={() => navigate('/kt/kh9/them')}>Thêm</Button>
        <Button variant="secondary" data-testid="ct-kh9-toolbar-edit-btn" disabled={noSelection} onClick={() => navigate(`/kt/kh9/${selectedSttRec}`)}>Sửa</Button>
        <Button variant="secondary" data-testid="ct-kh9-toolbar-view-btn" disabled={noSelection} onClick={() => navigate(`/kt/kh9/${selectedSttRec}?mode=view`)}>Xem</Button>
        <Button variant="secondary" data-testid="ct-kh9-toolbar-copy-btn" disabled={noSelection} onClick={() => navigate(`/kt/kh9/them?copyFrom=${encodeURIComponent(selectedSttRec)}`)}>Sao chép</Button>
      </div>

      <section className={df.section} data-testid="ct-kh9-search">
        <h2 className={df.sectionTitle}>Tìm kiếm</h2>
        <div className={df.row4} onKeyDown={onEnter}>
          <div>
            <label className={df.label}>Ngày chứng từ từ</label>
            <Input type="date" data-testid="ct-kh9-search-ngayCt1" value={search.ngayCt1} onChange={setText('ngayCt1')} />
          </div>
          <div>
            <label className={df.label}>Ngày chứng từ đến</label>
            <Input type="date" data-testid="ct-kh9-search-ngayCt2" value={search.ngayCt2} onChange={setText('ngayCt2')} />
          </div>
          <div>
            <label className={df.label}>Số kế hoạch từ</label>
            <Input maxLength={30} data-testid="ct-kh9-search-soCt1" value={search.soCt1} onChange={setText('soCt1')} />
          </div>
          <div>
            <label className={df.label}>Số kế hoạch đến</label>
            <Input maxLength={30} data-testid="ct-kh9-search-soCt2" value={search.soCt2} onChange={setText('soCt2')} />
          </div>
          <Field label="Đối tượng" testId="ct-kh9-search-maKh" value={search.maKh} onChange={setText('maKh')} />
          <Field label="Kho" testId="ct-kh9-search-maKho" value={search.maKho} onChange={setText('maKho')} />
          <Field label="Vật tư" testId="ct-kh9-search-maVt" value={search.maVt} onChange={setText('maVt')} />
          <div className={df.spanCol2}>
            <label className={df.label}>Diễn giải</label>
            <Input maxLength={200} data-testid="ct-kh9-search-dienGiai" value={search.dienGiai} onChange={setText('dienGiai')} />
          </div>
          <Select
            label="Loại giao dịch"
            data-testid="ct-kh9-search-maGd"
            value={search.maGd}
            options={[
              { value: '', label: 'Tất cả' },
              { value: '2', label: 'KH chi phí' },
              { value: '4', label: 'KH doanh thu' },
            ]}
            onChange={event => setSearch(prev => ({ ...prev, maGd: event.target.value }))}
          />
        </div>
        <Button variant="primary" data-testid="ct-kh9-search-btn" onClick={onSearch}>Tìm</Button>
      </section>

      <section className={df.section} data-testid="ct-kh9-search-extra">
        <h2 className={df.sectionTitle}>Điều kiện thêm</h2>
        <div className={df.row4} onKeyDown={onEnter}>
          <Select
            label="Trạng thái"
            data-testid="ct-kh9-search-maPost"
            value={search.maPost}
            options={[
              { value: '3', label: 'Lập kế hoạch' },
              { value: '9', label: 'Kế hoạch đã phê duyệt' },
            ]}
            onChange={event => setSearch(prev => ({ ...prev, maPost: event.target.value }))}
          />
          <Field label="Nhóm vật tư 1" testId="ct-kh9-search-nhVt1" value={search.nhVt1} onChange={setText('nhVt1')} />
          <Field label="Nhóm vật tư 2" testId="ct-kh9-search-nhVt2" value={search.nhVt2} onChange={setText('nhVt2')} />
          <Field label="Nhóm vật tư 3" testId="ct-kh9-search-nhVt3" value={search.nhVt3} onChange={setText('nhVt3')} />
          <Field label="Nhóm vật tư 4" testId="ct-kh9-search-nhVt4" value={search.nhVt4} onChange={setText('nhVt4')} />
          <Field label="Nhóm vật tư 5" testId="ct-kh9-search-nhVt5" value={search.nhVt5} onChange={setText('nhVt5')} />
          <Field label="Tiền NT từ" testId="ct-kh9-search-tien1" value={search.tien1} onChange={setText('tien1')} inputMode="decimal" />
          <Field label="Tiền NT đến" testId="ct-kh9-search-tien2" value={search.tien2} onChange={setText('tien2')} inputMode="decimal" />
          <Field label="Khoản mục" testId="ct-kh9-search-maPhi" value={search.maPhi} onChange={setText('maPhi')} />
          <Field label="Vụ việc" testId="ct-kh9-search-maVv" value={search.maVv} onChange={setText('maVv')} />
          <Field label="Hợp đồng" testId="ct-kh9-search-maHd" value={search.maHd} onChange={setText('maHd')} />
          <Field label="Sản phẩm" testId="ct-kh9-search-maSp" value={search.maSp} onChange={setText('maSp')} />
          <Field label="Khế ước" testId="ct-kh9-search-maKu" value={search.maKu} onChange={setText('maKu')} />
          <Field label="Trung tâm lợi nhuận" testId="ct-kh9-search-maTtln" value={search.maTtln} onChange={setText('maTtln')} />
          <Field label="Trung tâm chi phí" testId="ct-kh9-search-maTtcp" value={search.maTtcp} onChange={setText('maTtcp')} />
          <Field label="Bộ phận" testId="ct-kh9-search-maBp" value={search.maBp} onChange={setText('maBp')} />
          <Field label="Nhân sự" testId="ct-kh9-search-maHs" value={search.maHs} onChange={setText('maHs')} />
          <Field label="Công đoạn" testId="ct-kh9-search-maCd" value={search.maCd} onChange={setText('maCd')} />
          <Field label="Mã tự do 1" testId="ct-kh9-search-maTd1" value={search.maTd1} onChange={setText('maTd1')} />
          <Field label="Mã tự do 2" testId="ct-kh9-search-maTd2" value={search.maTd2} onChange={setText('maTd2')} />
          <Field label="Mã tự do 3" testId="ct-kh9-search-maTd3" value={search.maTd3} onChange={setText('maTd3')} />
          <Field label="Mã tự do 4" testId="ct-kh9-search-maTd4" value={search.maTd4} onChange={setText('maTd4')} />
          <Field label="Mã tự do 5" testId="ct-kh9-search-maTd5" value={search.maTd5} onChange={setText('maTd5')} />
          <div>
            <Checkbox
              label="Chỉ chứng từ của tôi"
              data-testid="ct-kh9-search-locNsd"
              checked={search.locNsd}
              onChange={event => setSearch(prev => ({ ...prev, locNsd: event.target.checked }))}
            />
          </div>
        </div>
      </section>

      {error ? <div className={df.errorBanner}>{error}</div> : null}
      {loading ? <div className={df.loading}>Đang tải...</div> : null}

      <div className={df.tableWrapper}>
        <table className={df.linesTable} data-testid="ct-kh9-grid">
          <thead>
            <tr>
              <th>Số kế hoạch</th>
              <th>Kế hoạch từ ngày</th>
              <th>Kế hoạch đến ngày</th>
            </tr>
          </thead>
          <tbody>
            {items.map(row => (
              <tr
                key={row.sttRec}
                aria-selected={row.sttRec === selectedSttRec}
                style={row.sttRec === selectedSttRec ? { background: 'var(--ds-color-primary-bg, rgba(13, 110, 253, 0.08))' } : undefined}
                onClick={() => setSelectedSttRec(row.sttRec)}
              >
                <td>{row.soCt}</td>
                <td>{formatDate(row.ngayKh1)}</td>
                <td>{formatDate(row.ngayKh2)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {items.length === 0 && !loading ? (
        <div>{filtering ? 'Không tìm thấy kế hoạch tài chính' : 'Không có kế hoạch tài chính'}</div>
      ) : null}
    </div>
  );
};

const Field: React.FC<{
  label: string;
  testId: string;
  value: string;
  onChange: (event: React.ChangeEvent<HTMLInputElement>) => void;
  inputMode?: 'decimal';
}> = ({ label, testId, value, onChange, inputMode }) => (
  <div>
    <label className={df.label}>{label}</label>
    <Input maxLength={inputMode ? undefined : 30} inputMode={inputMode} data-testid={testId} value={value} onChange={onChange} />
  </div>
);

export default Kh9ListPage;
